EXPECTED_SHA256 = "b6187600434b2834ce67d314ca04bd0f866eb29bdd5f2d4f13ba0f6b75930689"

def materialize() -> dict[str, bytes]:
    files: dict[str, bytes] = {}
    for operation, df, initial_offset in DF_CASES:
        case_id = f"s2_19i_rep_restart_{operation}_df{df}"
        code = bytes.fromhex({"stosb": "4885c0f3aa", "lodsb": "4885c0f3ac", "movsb": "4885c0f3a4"}[operation])
        gprs = BASE_GPRS.copy()
        gprs[6 if operation == "lodsb" else 7] = (
            BASE if operation != "movsb" else DESTINATION_BASE
        ) + initial_offset
        if operation == "movsb":
            gprs[6] = BASE + initial_offset
        flags = (0x0CD7 if df else 0x08D7)
        code_region = {
            "region_id": "code",
            "guest_address": hx(RIP),
            "length": len(code),
            "permissions": {"read": False, "write": False, "execute": True},
            "initial_bytes_hex": code.hex(),
            "comparison_mask_hex": "ff" * len(code),
        }
        regions = [code_region]
        if operation == "lodsb":
            regions.append({
                "region_id": "source", "guest_address": hx(BASE), "length": DATA_LENGTH,
                "permissions": {"read": True, "write": False, "execute": False},
                "initial_bytes_hex": DATA, "comparison_mask_hex": "ff" * DATA_LENGTH,
            })
        elif operation == "stosb":
            regions.append({
                "region_id": "destination", "guest_address": hx(BASE), "length": DATA_LENGTH,
                "permissions": {"read": True, "write": True, "execute": False},
                "initial_bytes_hex": ZEROES, "comparison_mask_hex": "ff" * DATA_LENGTH,
            })
        else:
            regions.extend([
                {
                    "region_id": "source", "guest_address": hx(BASE), "length": DATA_LENGTH,
                    "permissions": {"read": True, "write": False, "execute": False},
                    "initial_bytes_hex": DATA, "comparison_mask_hex": "ff" * DATA_LENGTH,
                },
                {
                    "region_id": "destination", "guest_address": hx(DESTINATION_BASE), "length": DATA_LENGTH,
                    "permissions": {"read": True, "write": True, "execute": False},
                    "initial_bytes_hex": ZEROES, "comparison_mask_hex": "ff" * DATA_LENGTH,
                },
            ])
        fixture = {
            "schema_version": 2,
            "case_id": case_id,
            "profile": "s2-long-integer-v1",
            "provenance": {
                "kind": "project_fixture",
                "source": "Handwritten instruction bytes, input state, and complete partial/resumed snapshots; this generator serializes fixed cases only.",
                "specification": (
                    "Intel SDM revision 093, Vol.2A LODS and REP entries: completed "
                    "iterations update count and source index, while a partial invocation "
                    "leaves RIP on the repeated instruction for continuation."
                    if operation == "lodsb"
                    else "Intel SDM revision 093, Vol.2B STOS/MOVS and REP entries: completed "
                    "iterations update count and the relevant index state, while a partial "
                    "invocation leaves RIP on the repeated instruction for continuation."
                ),
                "specification_version": (
                    "Intel SDM Vol.2A revision 093 (253666-093US); project S2-19i REP LODSB"
                    if operation == "lodsb"
                    else "Intel SDM Vol.2B revision 093 (253667-093US); project S2-19i"
                ),
            },
            "seed": None,
            "converted_from_v1_sha256": None,
            "initial_state": {"mode": "long64", "gpr": [hx(value) for value in gprs], "rip": hx(RIP), "rflags": hx(flags)},
            "memory": regions,
            "stop_rip": hx(RIP + len(code)),
            "instruction_budget": 2,
            "wall_timeout_ms": 2000,
            "rflags_mask": hx(0x0CD7),
            "expected_exit": "rep_iteration_budget_exhausted",
        }
        files[f"{case_id}.case.json"] = dump(fixture)
    files["s2_19i_rep_restart_expected.json"] = dump(EXPECTED)
    return files


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    mismatches = []
    generated = materialize()
    for name, contents in generated.items():
        path = FIXTURES / name
        if args.check:
            if not path.exists() or path.read_bytes() != contents:
                mismatches.append(str(path.relative_to(ROOT)))
        else:
            path.write_bytes(contents)
    if mismatches:
        print("stale generated files: " + ", ".join(mismatches))
        return 1
    print("S2-19i REP restart fixtures are fresh" if args.check else f"wrote {len(generated)} S2-19i files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
